var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.1/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/specification_section_divisions?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&specification_area_id=SOME_STRING_VALUE&id=SOME_STRING_VALUE&search_string=SOME_STRING_VALUE&specification_set_ids=SOME_ARRAY_VALUE&with_sections=SOME_STRING_VALUE&view=SOME_STRING_VALUE&no_filter=SOME_BOOLEAN_VALUE"),
};
